package com.trampolim.api.hub;
import java.util.*;
import static com.trampolim.api.hub.HubRules.*;import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.security.PlatformAccess;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.web.server.ResponseStatusException;import org.springframework.transaction.annotation.Transactional;
@RestController
@RequestMapping("/api/admin/hub")
@ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class HubAdminController {
 private final HubService service;private final PlatformAccess platform;private final JdbcTemplate jdbc;
 public HubAdminController(HubService service,PlatformAccess platform,@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc){this.service=service;this.platform=platform;this.jdbc=jdbc;}
 private void admin(String email){if(!platform.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Acesso restrito à administração geral.");}
 public record Create(String name,Profile profile){}public record State(String status){}
 @GetMapping("/organizations")public Map<String,Object> list(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String q){admin(email);page(before,limit);text(q,120);return HubService.pageResult(jdbc.queryForList("SELECT id,name,status FROM enterprise_organizations WHERE organization_type='ASSOCIATION' AND id<? AND (?='' OR name ILIKE ?) ORDER BY id DESC LIMIT ?",before,q,"%"+q+"%",limit+1),limit);}
 @PostMapping("/organizations")@Transactional("empresasTransactionManager")public Map<String,Object> create(@AuthenticationPrincipal String email,@RequestBody Create body){admin(email);if(body==null||text(body.name(),180).isEmpty())bad("Informe nome institucional.");HubRules.profile(body.profile());long id=jdbc.queryForObject("INSERT INTO enterprise_organizations(name,organization_type,status) VALUES (?,'ASSOCIATION','PENDING') RETURNING id",Long.class,body.name().trim());service.saveProfile(id,email,body.profile());service.audit(id,email,"HUB_ASSOCIATION_CREATED");return Map.of("id",id,"status","PENDING");}
 @GetMapping("/organizations/{id}/profile")public Map<String,Object> profile(@AuthenticationPrincipal String email,@PathVariable long id){admin(email);return service.profile(id);}
 @PutMapping("/organizations/{id}/profile")public Map<String,Object> profile(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Profile body){admin(email);return service.saveProfile(id,email,body);}
 @PutMapping("/organizations/{id}/status")@Transactional("empresasTransactionManager")public Map<String,Object> state(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody State input){admin(email);service.exists(id);if(input==null||!Set.of("ACTIVE","PENDING","SUSPENDED").contains(Objects.toString(input.status(),"")))bad("Situação inválida.");var p=service.profile(id);if(input.status().equals("ACTIVE")&&(Objects.toString(p.get("legal_name"),"").isBlank()||Objects.toString(p.get("contact_email"),"").isBlank()||Objects.toString(p.get("responsible_name"),"").isBlank()))bad("Preencha nome legal, contato e responsável antes de ativar o Hub.");jdbc.update("UPDATE enterprise_organizations SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.status(),id);service.audit(id,email,"HUB_ASSOCIATION_STATUS_CHANGED");return Map.of("status",input.status());}
 @GetMapping("/organizations/{id}/companies")public Map<String,Object> companies(@AuthenticationPrincipal String email,@PathVariable long id,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit){admin(email);service.exists(id);return service.companies(id,before,limit);}
 @GetMapping("/plans")public List<Map<String,Object>> plans(@AuthenticationPrincipal String email){admin(email);return service.plans();}
 @PostMapping("/plans")public Map<String,Object> plan(@AuthenticationPrincipal String email,@RequestBody Plan input){admin(email);return service.plan(email,input);}
 @PutMapping("/plans/{id}/status")public void planState(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody State input){admin(email);if(input==null||!Set.of("ACTIVE","DRAFT","ARCHIVED").contains(Objects.toString(input.status(),"")))bad("Situação inválida.");if(jdbc.update("UPDATE hub_institutional_plans SET status=? WHERE id=?",input.status(),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);service.auditPlan(id,email,"HUB_PLAN_STATUS_CHANGED");}
 @GetMapping("/organizations/{id}/contracts")public List<Map<String,Object>> contracts(@AuthenticationPrincipal String email,@PathVariable long id){admin(email);service.exists(id);return service.contracts(id);}
 @PostMapping("/organizations/{id}/contracts")public Map<String,Object> contract(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Contract input){admin(email);return service.contract(id,0,email,input);}
 @PutMapping("/organizations/{id}/contracts/{cid}")public Map<String,Object> contract(@AuthenticationPrincipal String email,@PathVariable long id,@PathVariable long cid,@RequestBody Contract input){admin(email);return service.contract(id,cid,email,input);}
 @GetMapping("/organizations/{id}/usage")public Map<String,Object> usage(@AuthenticationPrincipal String email,@PathVariable long id){admin(email);return service.usage(id);}
}
